import * as T from './assets/three.module.js';
import {divisionState} from './division-science.js';
export function createDivisionModel(host){
 let renderer;try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'})}catch{return {draw(mode,index){const s=divisionState(mode,index);host.innerHTML=`<div class="division-fallback">${Array.from({length:s.cells},()=>`<div>${Array.from({length:s.nst},(_,i)=>`<b style="color:${i%2?'#9e8b61':'#658e79'}">${s.replicated?'X':'Ⅰ'}</b>`).join('')}</div>`).join('')}</div>`},resize(){}}}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setClearColor(0x000000,0);host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Mô hình ba chiều tế bào và nhiễm sắc thể');
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(33,1,.1,100);camera.position.set(0,3,15);camera.lookAt(0,0,0);scene.add(new T.HemisphereLight(0xf9f4da,0x537c65,2.4));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-4,6,8);scene.add(light);const group=new T.Group();scene.add(group);let drag=null,angle=-.16,animationFrame=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const chromosome=(replicated,color)=>{const g=new T.Group(),mat=new T.MeshStandardMaterial({color,roughness:.38,metalness:.05});for(const sign of replicated?[-1,1]:[0]){const rod=new T.Mesh(new T.CapsuleGeometry(.1,.82,5,10),mat);rod.rotation.z=sign*.45;g.add(rod)}const bead=new T.Mesh(new T.SphereGeometry(.115,12,8),mat);g.add(bead);return g};
 function clear(){group.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose()}});group.clear()}
 function render(){group.rotation.y=angle;renderer.render(scene,camera)}
 function resize(){const w=host.clientWidth||600,h=host.clientHeight||370;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();render()}
 function draw(mode,index){cancelAnimationFrame(animationFrame);animationFrame=0;clear();const s=divisionState(mode,index),centres=s.cells===1?[[0,0]]:s.cells===2?[[-2.3,0],[2.3,0]]:[[-2,1.3],[2,1.3],[-2,-1.3],[2,-1.3]],radius=s.cells===4?1.4:s.cells===2?1.85:2.65;
 for(const [ci,[cx,cy]] of centres.entries()){
  const cell=new T.Group();cell.position.set(cx,cy,0);group.add(cell);const shell=new T.Mesh(new T.SphereGeometry(radius,40,28),new T.MeshPhysicalMaterial({color:0xc6dcae,transparent:true,opacity:.15,roughness:.35,side:T.DoubleSide,depthWrite:false}));shell.scale.z=.45;cell.add(shell);const ring=new T.Mesh(new T.TorusGeometry(radius,.025,6,80),new T.MeshStandardMaterial({color:0x6d9979,transparent:true,opacity:.55}));cell.add(ring);
  for(let i=0;i<s.nst;i++){const color=(mode==='meiosis'&&s.cells>1?ci%2:i%2)?0xb69a74:0x688caa,g=chromosome(s.replicated,color);let x,y;if(s.separated){const homologues=mode==='meiosis'&&s.cells===1&&s.replicated;x=(homologues?(i%2?1:-1):(i<s.nst/2?-1:1))*radius*.5;y=((homologues?Math.floor(i/2):i%(s.nst/2))-(s.nst/2-1)/2)*.5}else if(s.equator||s.paired){x=s.paired?(i%2? .26:-.26):0;y=(s.paired?Math.floor(i/2)-(s.nst/2-1)/2:i-(s.nst-1)/2)*.65}else{x=Math.cos(i/s.nst*Math.PI*2)*radius*.45;y=Math.sin(i/s.nst*Math.PI*2)*radius*.38}g.position.set(x,y,.12);g.scale.setScalar(s.cells===4?.75:1);const poleIndex=s.separated?i%(s.nst/2):i,isLong=s.separated?(mode==='meiosis'&&s.cells===1&&s.replicated?i<2:poleIndex<Math.max(1,s.nst/4)):s.cells===1?i<2:i%2===0;g.scale.y*=isLong?1:.66;if(s.separated){g.userData.targetX=x;if(!reduced.matches)g.position.x=0}cell.add(g)}
  if(s.equator||s.separated){const points=[new T.Vector3(-radius*.86,0,0),new T.Vector3(radius*.86,0,0)];for(let j=0;j<5;j++){const points2=[points[0],new T.Vector3(0,(j-2)*radius*.27,0),points[1]],geometry=new T.BufferGeometry().setFromPoints(points2);cell.add(new T.Line(geometry,new T.LineBasicMaterial({color:0x9ca97e,transparent:true,opacity:.25})))}}
 }resize();if(s.separated&&!reduced.matches){const start=performance.now();const step=now=>{const t=Math.min(1,(now-start)/1000),k=1-(1-t)**3;group.traverse(o=>{if(o.userData.targetX!==undefined)o.position.x=o.userData.targetX*k});render();if(t<1)animationFrame=requestAnimationFrame(step);else animationFrame=0};animationFrame=requestAnimationFrame(step)}}
 renderer.domElement.addEventListener('pointerdown',e=>{drag={x:e.clientX,angle};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(drag){angle=drag.angle+(e.clientX-drag.x)*.006;render()}});for(const name of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(name,()=>drag=null);new ResizeObserver(resize).observe(host);return {draw,resize,setActive(value){if(!value){cancelAnimationFrame(animationFrame);animationFrame=0;group.traverse(o=>{if(o.userData.targetX!==undefined)o.position.x=o.userData.targetX})}else resize()}};
}
